changeSet.sql:
CREATE INDEX IF NOT EXISTS idx_sales_company_store_created
  ON sales (company_id, store_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_sales_completed_created
  ON sales (created_at DESC)
  WHERE status = 'COMPLETED';

CREATE INDEX IF NOT EXISTS idx_sale_items_sale_id
  ON sale_items (sale_id);

CREATE INDEX IF NOT EXISTS idx_products_company_active
  ON products (company_id, is_active);

CREATE INDEX IF NOT EXISTS idx_stock_movements_store_created
  ON stock_movements (store_id, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_finance_sync_outbox_status_created
  ON finance_sync_outbox (status, created_at DESC);
